cat > /tmp/setup_alpine_guest.sh <<'EOS'
#!/bin/sh
set -x
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
apk add --no-cache --allow-untrusted openssh-server openssh-client openssh-keygen
printf 'root:password123\n' | chpasswd
sed -i -e 's/^#\?PermitRootLogin.*/PermitRootLogin yes/' -e 's/^#\?PasswordAuthentication.*/PasswordAuthentication yes/' /etc/ssh/sshd_config
grep -q '^PermitRootLogin' /etc/ssh/sshd_config || echo 'PermitRootLogin yes' >> /etc/ssh/sshd_config
grep -q '^PasswordAuthentication' /etc/ssh/sshd_config || echo 'PasswordAuthentication yes' >> /etc/ssh/sshd_config
ssh-keygen -A
mkdir -p /run/sshd
IFACE=$(ls /sys/class/net | grep -v '^lo$' | head -n1)
ip link set "$IFACE" up
udhcpc -i "$IFACE" -n -q -t 20 || true
rc-service sshd start || /etc/init.d/sshd start || /usr/sbin/sshd
netstat -lnt | grep ':22'
EOS
chmod +x /tmp/setup_alpine_guest.sh
cat > /tmp/run_alpine.exp <<'EOS'
#!/usr/bin/expect -f
set timeout 300
log_file -a /tmp/alpine-console.log
set guestscript [exec cat /tmp/setup_alpine_guest.sh]
spawn qemu-system-x86_64 -m 1024 -smp 2 -accel tcg,thread=multi -nographic -boot d -cdrom /app/alpine.iso -hda /app/alpine-disk.qcow2 -netdev user,id=net0,hostfwd=tcp:127.0.0.1:2222-:22 -device virtio-net-pci,netdev=net0 -no-reboot
expect {
  -re {login: ?$} {}
  timeout { puts "TIMEOUT waiting for login"; exit 1 }
}
send "root\r"
expect {
  -re {# } {}
  timeout { puts "TIMEOUT waiting for shell"; exit 1 }
}
send "cat >/tmp/setup_alpine_guest.sh <<'ENDOFGUESTSCRIPT'\r"
send -- $guestscript
send "\rENDOFGUESTSCRIPT\r"
send "sh /tmp/setup_alpine_guest.sh; printf '__SETUP_%s__\\n' DONE\r"
expect {
  "__SETUP_DONE__" {}
  timeout { puts "TIMEOUT waiting for setup"; exit 1 }
}
send "\r"
expect -re {# }
puts "SETUP COMPLETE"
expect eof
EOS
chmod +x /tmp/run_alpine.exp
rm -f /tmp/alpine-console.log /tmp/run_alpine.out
setsid nohup expect /tmp/run_alpine.exp > /tmp/run_alpine.out 2>&1 < /dev/null &
echo "started pid $!"; sleep 5; ps aux | grep -E 'expect|qemu' | grep -v grep

cat > /tmp/test_ssh.exp <<'EOS'
#!/usr/bin/expect -f
set timeout 30
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PreferredAuthentications=password -o PubkeyAuthentication=no root@localhost
expect {
  -re {[Pp]assword:} { send "password123\r" }
  timeout { puts "NO_PASSWORD_PROMPT"; exit 1 }
}
expect {
  -re {# } { send "echo SSH_VERIFIED; uname -a; id\r" }
  timeout { puts "NO_SHELL"; exit 1 }
}
expect "SSH_VERIFIED"
expect -re {# }
send "exit\r"
expect eof
puts "SSH_TEST_OK"
EOS
chmod +x /tmp/test_ssh.exp
timeout 45 expect /tmp/test_ssh.exp > /tmp/test_ssh.out 2>&1; echo "exit=$?"; cat -v /tmp/test_ssh.out; echo '---processes---'; for p in /proc/[0-9]*; do c=$(tr '\0' ' ' < $p/cmdline 2>/dev/null); case "$c" in *qemu-system*|*run_alpine.exp*) echo "${p##*/}: $c";; esac; done
